using System;using System.IO;using System.Linq;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class FixTelevisionLeadCycle02{
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene");const string path="Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity";const string backup="outputs/chapter45-detailed-design-2026-10-03/behavior-cycle02/recovery/ShoeTower.before-tv-lead.unity";if(File.Exists(backup))throw new Exception("Do not reapply");var setup=EditorSceneManager.GetSceneManagerSetup();try{var scene=EditorSceneManager.OpenScene(path);var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();var h=d.hazards.Single(x=>x.name=="4F falling television");if(h.warningDistance!=18)throw new Exception("Unexpected baseline");var old=EditorJsonUtility.ToJson(h);File.Copy(path,backup);File.Copy(path+".meta",backup+".meta");h.warningDistance=22;EditorUtility.SetDirty(h);var expected=EditorJsonUtility.ToJson(h);if(expected!=old.Replace("\"warningDistance\":18.0","\"warningDistance\":22.0"))throw new Exception("Unexpected runtime property diff");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);EditorSceneManager.OpenScene(path);h=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>().hazards.Single(x=>x.name=="4F falling television");if(h.warningDistance!=22)throw new Exception("Save verification failed");return new{scene=path,hazard=h.name,beforeWarningDistance=18,afterWarningDistance=h.warningDistance,h.warningSeconds,h.operationSeconds,h.damageFraction,h.safeLane,h.safeHalfWidth,backup,onlyChangedProperty="warningDistance",reopened=true};}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}}
}
